// Recibe el JSON de domotica/habitacion/estado (cada 10 s)
const p = msg.payload;
if (typeof p !== 'object' || p === null) return null;

const num = v => (typeof v === 'number' && Number.isFinite(v)) ? v : null;

const m = context.get('muestras') || [];
m.push({
  temp: num(p.temp),
  hum: num(p.hum),
  rssi: num(p.rssi),
  heap_libre: num(p.heap_libre),
  uptime: num(p.uptime)
});
context.set('muestras', m);

// Registrar el relé solo cuando cambia
if (typeof p.luz === 'boolean') {
  const anterior = context.get('luz');
  if (anterior !== p.luz) {
    context.set('luz', p.luz);
    try {
      context.get('st').rele.run('esp32-habitacion', 'luz', p.luz ? 1 : 0, anterior === undefined ? 'inicio' : 'esp32');
    } catch (e) {
      node.error('SQLite: ' + e.message);
    }
  }
}
return null;

