// LEANDRO HOME SERVER - Etapa 6: abre la BD una sola vez
const { DatabaseSync } = global.get('sqlite');
const db = new DatabaseSync('/srv/servidor/bases_datos/domotica.db');
db.exec('PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000; PRAGMA foreign_keys=ON;');

const DISP = 'esp32-habitacion';
const st = {
  lectura:  db.prepare('INSERT INTO lecturas (dispositivo, temperatura, humedad, rssi, heap_libre, uptime) VALUES (?, ?, ?, ?, ?, ?)'),
  contacto: db.prepare("UPDATE dispositivos SET ultimo_contacto = datetime('now','localtime') WHERE id = ?"),
  rele:     db.prepare('INSERT INTO estados_rele (dispositivo, rele, estado, origen) VALUES (?, ?, ?, ?)'),
  evento:   db.prepare('INSERT INTO eventos (nivel, origen, mensaje) VALUES (?, ?, ?)')
};

const promedio = (m, k) => {
  const v = m.map(x => x[k]).filter(Number.isFinite);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
};
const r1 = x => x === null ? null : Math.round(x * 10) / 10;

// Cada 60 s guarda el promedio de las muestras recibidas
const guardar = () => {
  try {
    const m = context.get('muestras') || [];
    context.set('muestras', []);
    if (m.length === 0) {
      if (context.get('online')) {
        context.set('online', false);
        st.evento.run('warning', DISP, 'Sin datos durante 1 minuto');
      }
      node.status({ fill: 'red', shape: 'ring', text: 'sin datos ' + new Date().toLocaleTimeString() });
      return;
    }
    if (!context.get('online')) {
      context.set('online', true);
      st.evento.run('info', DISP, 'Vuelve a enviar datos');
    }
    const ult = m[m.length - 1];
    const t = r1(promedio(m, 'temp'));
    const h = r1(promedio(m, 'hum'));
    const r = promedio(m, 'rssi');
    st.lectura.run(DISP, t, h, r === null ? null : Math.round(r), ult.heap_libre, ult.uptime);
    st.contacto.run(DISP);
    node.status({ fill: 'green', shape: 'dot', text: `${t}°C ${h}% · ${m.length} muestras · ${new Date().toLocaleTimeString()}` });
  } catch (e) {
    node.error('SQLite: ' + e.message);
  }
};

context.set('db', db);
context.set('st', st);
context.set('muestras', []);
context.set('online', true);
context.set('timer', setInterval(guardar, 60000));
st.evento.run('info', 'nodered', 'Registro de historial iniciado');
node.status({ fill: 'blue', shape: 'ring', text: 'BD abierta, esperando datos' });

finalize:
clearInterval(context.get('timer'));
try { context.get('st').evento.run('info', 'nodered', 'Registro de historial detenido'); } catch (e) {}
try { context.get('db').close(); } catch (e) {}

